scripts.streaks-report:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'streaks-report',
  description: 'Summarize check-in counts for every habit in habits.json.',
  kind: 'action',
  inputs: {},
  outputs: {
    report: { type: 'string', description: 'One line per habit with its check-in count.' },
  },
  requires: ['workspace.read'],
} as const);

const raw = await gezel.fs.read('habits.json').catch(() => '{"habits":[]}');
const data = JSON.parse(raw) as { habits: Array<{ name: string; log: string[] }> };
const lines = data.habits.map((habit) => `${habit.name}: ${habit.log.length} check-ins`);
gezel.output({ report: lines.join('\n') || 'No habits yet.' });
